import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { findUser } from '../utils/storage';
import './AuthPage.css';

export default function LoginPage() {
  const [form, setForm] = useState({ email: '', password: '', role: 'student' });
  const [errors, setErrors] = useState({});
  const [apiError, setApiError] = useState('');
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const validate = () => {
    const e = {};
    if (!form.email.trim()) e.email = 'Email is required';
    else if (!/\S+@\S+\.\S+/.test(form.email)) e.email = 'Enter a valid email';
    if (!form.password) e.password = 'Password is required';
    return e;
  };

  const handleChange = (e) => {
    setForm(p => ({ ...p, [e.target.name]: e.target.value }));
    setErrors(p => ({ ...p, [e.target.name]: '' }));
    setApiError('');
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const errs = validate();
    if (Object.keys(errs).length) { setErrors(errs); return; }

    setLoading(true);
    setTimeout(() => {
      const user = findUser(form.email, form.password);
      if (!user) {
        setApiError('Invalid email or password. Try demo@student.edu / password123');
        setLoading(false);
        return;
      }
      if (user.role !== form.role) {
        setApiError(`This account is registered as "${user.role}", not "${form.role}".`);
        setLoading(false);
        return;
      }
      login(user);
      navigate(user.role === 'admin' ? '/admin' : '/student');
    }, 600);
  };

  return (
    <div className="auth-page">
      <div className="auth-left">
        <div className="auth-left-content">
          <Link to="/" className="auth-logo">
            <span>🎓</span>
            <span>UniHelp</span>
          </Link>
          <blockquote className="auth-quote">
            "Empowering students with fast, transparent campus support."
          </blockquote>
          <div className="auth-decorative">
            <div className="deco-circle c1" />
            <div className="deco-circle c2" />
            <div className="deco-circle c3" />
          </div>
        </div>
      </div>

      <div className="auth-right">
        <div className="auth-form-container animate-fade-up">
          <div className="auth-form-header">
            <h1 className="auth-form-title">Welcome back</h1>
            <p className="auth-form-sub">Sign in to your UniHelp account</p>
          </div>

          {apiError && <div className="alert alert-error">{apiError}</div>}

          <form onSubmit={handleSubmit} noValidate>
            <div className="form-group">
              <label className="form-label">Email address</label>
              <input
                className={`form-input ${errors.email ? 'input-error' : ''}`}
                type="email"
                name="email"
                placeholder="your@email.edu"
                value={form.email}
                onChange={handleChange}
              />
              {errors.email && <span className="form-error">{errors.email}</span>}
            </div>

            <div className="form-group">
              <label className="form-label">Password</label>
              <input
                className={`form-input ${errors.password ? 'input-error' : ''}`}
                type="password"
                name="password"
                placeholder="Enter your password"
                value={form.password}
                onChange={handleChange}
              />
              {errors.password && <span className="form-error">{errors.password}</span>}
            </div>

            <div className="form-group">
              <label className="form-label">Sign in as</label>
              <div className="role-toggle">
                {['student', 'admin'].map(r => (
                  <button
                    key={r}
                    type="button"
                    className={`role-btn ${form.role === r ? 'active' : ''}`}
                    onClick={() => setForm(p => ({ ...p, role: r }))}
                  >
                    {r === 'student' ? '🎓 Student' : '🛠 Admin'}
                  </button>
                ))}
              </div>
            </div>

            <button type="submit" className="btn btn-primary btn-block" disabled={loading}>
              {loading ? <span className="btn-spinner" /> : 'Sign In'}
            </button>
          </form>

          <div className="auth-demo-hint">
            <strong>Demo accounts:</strong><br />
            Student: demo@student.edu / password123<br />
            Admin: admin@unihelp.edu / admin123
          </div>

          <p className="auth-switch">
            Don't have an account? <Link to="/signup">Create one</Link>
          </p>
        </div>
      </div>
    </div>
  );
}
